const ELK=['목','화','토','금','수'], ELH=['木','火','土','金','水'], ELV=['wood','fire','earth','metal','water'];
const TERM_DAY=[0,6,4,6,5,6,6,7,8,8,8,7,7]; // 양력 월별 절입일(근사)
