/* ================= 사주 할머니 말투 ================= */
const HB=0xAC00,isH=ch=>{const c=ch?ch.charCodeAt(0):0;return c>=HB&&c<=0xD7A3;},jongOf=ch=>(ch.charCodeAt(0)-HB)%28,setJong=(ch,j)=>String.fromCharCode(ch.charCodeAt(0)-jongOf(ch)+j);
const RIEUL={'뭅':'물','압':'알','듭':'들','엽':'열','팝':'팔','삽':'살','놉':'놀','법':'벌','풉':'풀','붑':'불','멉':'멀'};
const VERB_I=/(움직|보|쌓|줄|높|붙|기울|먹|끌|모|놓|섞|묶|뒤집|녹|숨|꺾|덮)$/;
let gmK=0;
function gmSent(t){
  const m=t.match(/^([\s\S]*?)(습니다|니다|세요)([.!?]?)(\s*)$/);if(!m)return t.replace(/까요\?/g,'까?');
  let [,base,end,pn,sp]=m;pn=pn||'.';
  if(end==='세요'){if(base.endsWith('으'))base=base.slice(0,-1);if(base.endsWith('마'))base=base.slice(0,-1)+'말';if(base.endsWith('만드'))base=base.slice(0,-1)+'들';return base+'거라'+pn+sp;}
  let cop=false;
  if(end==='니다'){const last=base.slice(-1);if(!isH(last)||jongOf(last)!==17)return t;
    if(RIEUL[last]&&base.length>1){base=base.slice(0,-1)+RIEUL[last];}
    else{cop=last==='입';base=base.slice(0,-1)+setJong(last,0);}}
  if(cop){const stem=base.slice(0,-1);if(!VERB_I.test(stem)){const prev=stem.replace(/\([^)]*\)$/,'').slice(-1);if(isH(prev)&&jongOf(prev)===0)base=stem;return base+'란다'+pn+sp;}}
  if(/[있없]$/.test(base))return base+'단다'+pn+sp;
  return base+((gmK++)%2===0?'지':'거든')+pn+sp;
}

/* ================= 성수동 편집샵 사장님 말투 ================= */
function haeche(stem){const l=stem.slice(-1);if(!isH(l))return stem+'어';const c=l.charCodeAt(0)-HB,cho=Math.floor(c/588),jung=Math.floor((c%588)/28),jong=c%28,pre=stem.slice(0,-1);
  const mk=j=>String.fromCharCode(HB+(cho*21+j)*28);
  if(l==='하')return pre+'해';
  if(l==='르'&&pre&&isH(pre.slice(-1))){const p=pre.slice(-1),pj=Math.floor(((p.charCodeAt(0)-HB)%588)/28);return pre.slice(0,-1)+setJong(p,8)+([0,8].includes(pj)?'라':'러');}
  if(jong)return stem+([0,8].includes(jung)?'아':'어');
  switch(jung){case 0:case 1:case 4:case 5:case 6:return stem;case 8:return pre+mk(9);case 13:return pre+mk(14);case 20:return pre+mk(6);case 11:return pre+mk(10);
   case 18:{const p=pre.slice(-1);let br=false;if(isH(p)){const pj=Math.floor(((p.charCodeAt(0)-HB)%588)/28);br=[0,8].includes(pj);}return pre+mk(br?0:4);}
   default:return stem+'어';}}
function bossSent(t){
  let m;
  if((m=t.match(/^([\s\S]*?지) 말거라([.!?]?)(\s*)$/)))return m[1]+' 마'+(m[2]||'.')+m[3];
  if((m=t.match(/^([\s\S]*?)말거라([.!?]?)(\s*)$/)))return m[1]+'하지 마'+(m[2]||'.')+m[3];
  if((m=t.match(/^([\s\S]*?)거라([.!?,]?)(\s*)$/)))return haeche(m[1])+(m[2]||'.')+m[3];
  if((m=t.match(/^([\s\S]*?)란다([.!?]?)(\s*)$/)))return m[1]+'야'+(m[2]||'.')+m[3];
  if((m=t.match(/^([\s\S]*?)단다([.!?]?)(\s*)$/)))return m[1]+'다니까'+(m[2]||'.')+m[3];
  if((m=t.match(/^([\s\S]*?)구나([.!?]?)(\s*)$/)))return m[1]+'네'+(m[2]||'.')+m[3];
  if((m=t.match(/^([\s\S]*?)게다([.!?]?)(\s*)$/)))return m[1]+'걸?'+m[3];
  if((m=t.match(/^([\s\S]*?)([가-힣])마([.!?])(\s*)$/))&&jongOf(m[2])===0)return m[1]+setJong(m[2],8)+'게'+m[3]+m[4];
  return t;}
function boss(t){if(t==null)return t;t=String(t).replace(/할미가/g,'제가').replace(/할미는/g,'저는').replace(/할미한테/g,'저한테').replace(/할미 말/g,'제 말').replace(/할미/g,'제가').replace(/아이고, /g,'오, ');
  t=t.split(/(?<=[.!?])\s+/).map(bossSent).join(' ');
  return t.replace(/(^|\s)아이야/g,'$1애야').replace(/(^|\s)아이란다/g,'$1애야').replace(/아이다\./g,'애다.');}
function gmBase(t){if(t==null)return t;t=String(t).replace(/당신의/g,'네').replace(/당신에게/g,'너한테').replace(/당신은/g,'너는').replace(/당신이/g,'네가').replace(/당신을/g,'너를').replace(/당신과/g,'너랑').replace(/당신 /g,'네 ').replace(/당신/g,'너').replace(/보셔도/g,'봐도');
  return t.split(/(?<=[.!?])\s+/).map(gmSent).join(' ');}

/* ===== 아틀리에 사장님: 해요체, 무심한 위트 ===== */
function yoSent(t){
  const m=t.match(/^([\s\S]*?)([가-힣])([.!?])(\s*)$/);if(!m)return t;let [,pre,last,p,sp]=m;const base=pre+last;
  if(last==='요')return t;
  if(last==='지')return pre+'죠'+p+sp;
  if(last==='야'){const prev=pre.slice(-1);if(prev==='이')return pre.slice(0,-1)+'이에요'+p+sp;return pre+(isH(prev)&&jongOf(prev)!==0?'이에요':'예요')+p+sp;}
  if(last==='다'){const prev=pre.slice(-1),stem=pre.slice(0,-1);
    if(pre.endsWith('는')){return haeche(pre.slice(0,-1))+'요'+p+sp;}
    if(pre.endsWith('아니'))return pre+'에요'+p+sp;
    if(prev==='이'&&pre.length>1)return pre.slice(0,-1)+(jongOf(pre.slice(-2,-1))?'이에요':'예요')+p+sp;
    if(isH(prev)&&jongOf(prev)===4)return haeche(stem+setJong(prev,0))+'요'+p+sp;
    if(prev==='니'&&pre.endsWith('다니'))return t;
    return haeche(pre)+'요'+p+sp;}
  if(/마라$/.test(base))return base.slice(0,-1)+'요'+p+sp;
  if(/[네든까게걸래잖며데]/.test(last))return base+'요'+p+sp;
  if(isH(last)&&jongOf(last)===0&&[0,1,4,5,6,9,10,14].includes(Math.floor(((last.charCodeAt(0)-HB)%588)/28)))return base+'요'+p+sp;
  return t;}
function yo(t){if(t==null)return t;t=String(t).replace(/([가-힣])이야,/g,'$1이에요,').replace(/너한텐/g,'본인한텐').replace(/너희 같은/g,'본인 같은').replace(/네가 /g,'본인이 ').replace(/너는 /g,'본인은 ').replace(/너한테/g,'본인한테').replace(/너를 /g,'본인을 ').replace(/너랑 /g,'본인이랑 ').replace(/(^|[\s(])네 /g,'$1본인 ').replace(/우리 /g,'우리 ');
  return t.split(/(?<=[.!?])\s+/).map(yoSent).join(' ');}
function gm(t){if(typeof t==='string'&&t.charCodeAt(0)===0x2060)return t.slice(1);return yo(boss(gmBase(t)));}
